void main() {
  vec3 col = vec3(0.0);
  for (int k = 0; k < 3; k++) {
    float o = 0.28 * (float(k) - 1.0);
    float d = uv.y - 0.5 - o - 0.45 * wave(uv.x + o, iTime);
    col += palette(0.16 + 0.10 * float(k) + 0.16 * uv.x) * exp(-d * d * 900.0);
  }
  gl_FragColor = vec4(col, 1.0);
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float d = length(p);
  float r = 0.5 + 0.5 * sin(d * 34.0 - iTime * 2.2);
  gl_FragColor = vec4(palette(0.30 + 0.30 * d) * pow(r, 4.0) * exp(-d * 2.4), 1.0);
}

void main() {
  vec3 a = texture2D(iChannel0, uv).rgb;
  vec3 b = texture2D(iChannel1, uv).rgb;
  float edge = uv.x - 0.5 + 0.35 * sin(iTime * 0.35) + 0.6 * wave(uv.y, iTime * 0.7);
  gl_FragColor = vec4(tone(mix(a, b, smoothstep(-blend, blend, edge)), 0.02, 1.6), 1.0);
}
